    -- Editor
    Normal = { fg = fg, bg = bg },
    NormalFloat = { fg = fg, bg = bg_alt },
    FloatBorder = { fg = c.ui3, bg = bg_alt },
    FloatTitle = { fg = accent, bg = bg_alt, bold = true },
    Cursor = { fg = bg, bg = focus },
    CursorLine = { bg = bg_alt },
    CursorColumn = { bg = bg_alt },
    ColorColumn = { bg = bg_alt },
    CursorLineNr = { fg = focus, bold = true },
    LineNr = { fg = c.ui3 },
    SignColumn = { bg = bg },
    FoldColumn = { fg = c.ui3 },
    Folded = { fg = fg3, bg = bg_alt },
    NonText = { fg = c.ui2 },
    Whitespace = { fg = c.ui2 },
    EndOfBuffer = { fg = bg },
    WinSeparator = { fg = c.ui2 },
    StatusLine = { fg = fg2, bg = c.ui1 },
    StatusLineNC = { fg = fg3, bg = bg_dim },
    TabLine = { fg = fg3, bg = bg_dim },
    TabLineFill = { bg = bg_dim },
    TabLineSel = { fg = fg, bg = bg, bold = true },
    WinBar = { fg = fg2, bg = bg },
    WinBarNC = { fg = fg3, bg = bg },
    Visual = { bg = c.hl1 },
    Search = { fg = fg, bg = c.search },
    CurSearch = { fg = bg, bg = focus, bold = true },
    IncSearch = { link = "CurSearch" },
    Substitute = { fg = bg, bg = c.red },
    MatchParen = { bg = c.ui2, bold = true },
    Pmenu = { fg = fg, bg = bg_alt },
    PmenuSel = { fg = fg, bg = c.ui2, bold = true },
    PmenuSbar = { bg = c.ui1 },
    PmenuThumb = { bg = c.ui3 },
    PmenuKind = { fg = c.caramel, bg = bg_alt },
    PmenuExtra = { fg = fg3, bg = bg_alt },
    Directory = { fg = c.blue },
    Title = { fg = accent, bold = true },
    ErrorMsg = { fg = c.red, bold = true },
    WarningMsg = { fg = c.yellow },
    MoreMsg = { fg = c.green },
    ModeMsg = { fg = fg2, bold = true },
    Question = { fg = c.green },
