    SpellCap = { undercurl = true, sp = c.yellow },
    SpellRare = { undercurl = true, sp = c.magenta },
    SpellLocal = { undercurl = true, sp = c.cyan },

    -- Diff and git
    DiffAdd = { bg = c.diff_add },
    DiffDelete = { fg = c.red, bg = c.diff_del },
    DiffChange = { bg = c.diff_change },
    DiffText = { bg = c.diff_text },
    Added = { fg = c.green },
    Changed = { fg = c.yellow },
    Removed = { fg = c.red },

    -- Syntax: keyword=ax1, function/number=caramel, string=brown, type/punctuation=tx2, comment=tx3
