    RenderMarkdownBullet = { fg = fg3 },
    RenderMarkdownTableHead = { fg = c.ui3 },
    RenderMarkdownTableRow = { fg = c.ui3 },
    RenderMarkdownChecked = { fg = focus },
    RenderMarkdownUnchecked = { fg = fg3 },
    RenderMarkdownLink = { fg = accent },
    SnacksIndent = { fg = c.ui1 },
    SnacksIndentScope = { fg = c.ui3 },
    SnacksPickerMatch = { fg = accent, bold = true },
    SnacksPickerDir = { fg = fg3 },
    NeoTreeNormal = { fg = fg, bg = bg },
    NeoTreeNormalNC = { fg = fg, bg = bg },
    NeoTreeDirectoryName = { fg = fg },
    NeoTreeDirectoryIcon = { fg = fg3 },
    NeoTreeRootName = { fg = accent, bold = true },
    NeoTreeIndentMarker = { fg = c.ui2 },
    NeoTreeGitModified = { fg = c.yellow },
    NeoTreeGitUntracked = { fg = fg3 },
    NeoTreeGitIgnored = { fg = c.ui3 },
    NeoTreeDotfile = { fg = fg3 },
    FlashLabel = { fg = bg, bg = accent, bold = true },
