end

--- Apply the colorscheme. `variant` ("light" or "dark") pins it; nil follows 'background'.
function M.load(variant)
  local name = variant and ("noeul-" .. variant) or "noeul"
  -- Neovim reloads the scheme when 'background' changes (e.g. terminal theme switch).
  -- A pinned variant keeps its colors then: setting 'background' back would make Neovim drop the scheme.
  local reloading = vim.g.colors_name == name
  vim.cmd("highlight clear")
  if vim.fn.exists("syntax_on") == 1 then
    vim.cmd("syntax reset")
  end
  if variant and not reloading then
    vim.o.background = variant
  end
  vim.g.colors_name = name

  local c = require("noeul.palette")[variant or vim.o.background]
  for name, spec in pairs(groups(c)) do
    vim.api.nvim_set_hl(0, name, spec)
  end
  for i, color in ipairs(c.ansi) do
    vim.g["terminal_color_" .. (i - 1)] = color
  end
end

return M
